        html: "<table>\n<thead><tr><th>Lo que ves</th><th>Qué significa</th><th>Qué hacer</th></tr></thead>\n<tbody>\n<tr><td>«El worker no responde; no se puede leer su estado.»</td><td>El programa no contesta a la web</td><td>Comprueba que el worker está encendido</td></tr>\n<tr><td>El estado pone <code>down</code></td><td>El worker se declara enfermo</td><td>Mira el dato concreto que lo delata</td></tr>\n<tr><td>Un aviso de error distinto</td><td>El worker contestó con un fallo raro</td><td>Vuelve a pulsar <strong>Actualizar</strong></td></tr>\n<tr><td>El retraso pasa de 50 bloques</td><td>El worker va muy por detrás</td><td>Revisa la conexión con la red</td></tr>\n<tr><td>El retraso sale en negativo</td><td>El worker cree estar por delante de la cadena</td><td>Suele pasar tras un reinicio. Avisa a quien mantiene el sistema</td></tr>\n<tr><td>Tres fallos seguidos de conexión</td><td>No consigue hablar con la red</td><td>Revisa el proveedor de la red</td></tr>\n<tr><td>Tres fallos seguidos de agregados</td><td>No consigue calcular los totales</td><td>Revisa la base de datos del worker</td></tr>\n<tr><td>El correo sale degradado</td><td>Los avisos por email no se entregan</td><td>Revisa la configuración de correo</td></tr>\n<tr><td>El proceso sale degradado</td><td>El último ciclo terminó con error</td><td>Mira los registros del worker</td></tr>\n<tr><td>Una casilla pone «…»</td><td>Ese dato no ha llegado</td><td>Pulsa <strong>Actualizar</strong></td></tr>\n<tr><td>Te pide volver a entrar</td><td>La sesión ha caducado</td><td>Entra de nuevo con tu cuenta</td></tr>\n</tbody></table>",
